package run.ikaros.music;
import java.nio.ByteBuffer; import java.nio.ByteOrder; import java.nio.charset.Charset; import java.nio.charset.StandardCharsets; import java.util.HashMap; import java.util.Map;
final class MusicTagParser {
    private MusicTagParser() {}
    static Parsed parse(String fileName, byte[] bytes) { Map<String,String> tags = new HashMap<>(); String source = "FILENAME"; if (bytes.length >= 10 && bytes[0]=='I' && bytes[1]=='D' && bytes[2]=='3') { parseId3(bytes,tags); source="ID3"; } else if (bytes.length >= 4 && bytes[0]=='f' && bytes[1]=='L' && bytes[2]=='a' && bytes[3]=='C') { parseFlac(bytes,tags); source="VORBIS"; } String fallback = baseName(fileName); return new Parsed(value(tags,"TITLE",fallback),value(tags,"ARTIST",null),value(tags,"ALBUM",null),value(tags,"ALBUMARTIST",null),value(tags,"ISRC",null),value(tags,"GENRE",null),number(tags,"TRACKNUMBER"),number(tags,"DISCNUMBER"),value(tags,"DATE",null),source); }
    private static void parseId3(byte[] b,Map<String,String> out) { int version=b[3]; int end=Math.min(b.length,10+synchsafe(b,6)); for(int p=10;p+10<=end;) { String id=new String(b,p,4,StandardCharsets.ISO_8859_1); int size=version>=4?synchsafe(b,p+4):int32(b,p+4); if(size<=0||p+10+size>end) break; if(id.startsWith("T")&& !id.equals("TXXX")) { String key=frameKey(id); if(key!=null) out.putIfAbsent(key,decodeText(b,p+10,size)); } p+=10+size; } }
    private static String frameKey(String id) { return switch(id) { case "TIT2"->"TITLE"; case "TPE1"->"ARTIST"; case "TALB"->"ALBUM"; case "TPE2"->"ALBUMARTIST"; case "TSRC"->"ISRC"; case "TCON"->"GENRE"; case "TRCK"->"TRACKNUMBER"; case "TPOS"->"DISCNUMBER"; case "TDRC","TYER"->"DATE"; default->null; }; }
    private static String decodeText(byte[] b,int start,int length) { if(length<1)return null; int encoding=b[start]&255; Charset charset=encoding==1||encoding==2?StandardCharsets.UTF_16:encoding==0?StandardCharsets.ISO_8859_1:StandardCharsets.UTF_8; return new String(b,start+1,length-1,charset).replace('\0',' ').trim(); }
    private static void parseFlac(byte[] b,Map<String,String> out) { int p=4; while(p+4<=b.length) { int head=b[p]&255; int size=((b[p+1]&255)<<16)|((b[p+2]&255)<<8)|(b[p+3]&255); p+=4; if(size<0||p+size>b.length)break; if((head&127)==4&&size>=8) { int vendor=len(b,p); int q=p+4+vendor; if(q+4<=p+size) { int count=len(b,q); q+=4; for(int i=0;i<count&&q+4<=p+size;i++){int n=len(b,q);q+=4;if(n<0||q+n>p+size)break;String entry=new String(b,q,n,StandardCharsets.UTF_8);q+=n;int eq=entry.indexOf('=');if(eq>0)out.putIfAbsent(entry.substring(0,eq).toUpperCase(),entry.substring(eq+1).trim());} } } p+=size; if((head&128)!=0)break; } }
    private static int len(byte[] b,int p){return p+4<=b.length?ByteBuffer.wrap(b,p,4).order(ByteOrder.LITTLE_ENDIAN).getInt():-1;} private static int synchsafe(byte[] b,int p){return ((b[p]&127)<<21)|((b[p+1]&127)<<14)|((b[p+2]&127)<<7)|(b[p+3]&127);} private static int int32(byte[]b,int p){return ByteBuffer.wrap(b,p,4).getInt();}
    private static Integer number(Map<String,String> tags,String key){try{String v=tags.get(key);return v==null?null:Integer.valueOf(v.split("/",2)[0].trim());}catch(Exception e){return null;}} private static String value(Map<String,String> tags,String key,String fallback){String v=tags.get(key);return v==null||v.isBlank()?fallback:v;} private static String baseName(String n){if(n==null||n.isBlank())return "未命名歌曲";int slash=Math.max(n.lastIndexOf('/'),n.lastIndexOf('\\'));String v=n.substring(slash+1);int dot=v.lastIndexOf('.');return dot>0?v.substring(0,dot):v;}
    record Parsed(String title,String artist,String album,String albumArtist,String isrc,String genre,Integer trackNumber,Integer discNumber,String releaseYear,String source) {}
}
